/* ----------------------------------------------------------------------------
 *  עזרים נגזרים — אין צורך לערוך מתחת לשורה זו.
 * -------------------------------------------------------------------------- */

// מפה לפי id לגישה מהירה: levelsById['strategic'] וכו'.
export const levelsById = levels.reduce((acc, level) => {
  acc[level.id] = level
  return acc
}, {})

// אפשרויות התשובה לשאלות (משותף לפירמידה ולמפה).
// shortLabel הוא הטקסט הקצר שמופיע על כפתורי התשובה.
const SHORT_LABELS = {
  strategic: 'אסטרטגית',
  operational: 'אופרטיבית',
  tactical: 'טקטית',
}

export const answerOptions = levels.map((level) => ({
  id: level.id,
  shortLabel: SHORT_LABELS[level.id] || level.nameHe,
  color: level.color,
}))

// טקסט המשוב כשהתשובה שגויה (משותף לכל הרמות).
export const wrongAnswerPrefix =
  'לא בדיוק. שים לב לקנה המידה, לאופק הזמן ולסוג ההחלטה. התשובה המתאימה כאן היא'
